INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('ssc-english-bank', NULL, 'English Language & Grammar (SSC)', 'ssc', 'shared', '2026-11-12T13:50:45.454Z', '2026-11-12T13:50:45.454Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('ssc-english-bank', 'ssc-exam');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q01', 'ssc-english-bank', 'English Language & Grammar', 0, 0, 'What is the difference between active voice and passive voice? Give an example.', 'In active voice, the subject performs the action (e.g., "The teacher explained the lesson"). In passive voice, the subject receives the action, and the doer becomes the object of the preposition "by" or is omitted (e.g., "The lesson was explained by the teacher"). Passive voice uses a form of "be" plus the past participle of the main verb.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q02', 'ssc-english-bank', 'English Language & Grammar', 0, 1, 'How do you convert a sentence from direct speech to indirect speech when the reporting verb is in the past tense?', 'When the reporting verb is in the past tense, the tense of the reported speech generally shifts backward (present simple becomes past simple, present continuous becomes past continuous, etc.), pronouns change according to the speaker/listener, and time/place references shift (e.g., "today" becomes "that day", "here" becomes "there"). Example: She said, "I am going to the market" becomes She said that she was going to the market.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q03', 'ssc-english-bank', 'English Language & Grammar', 0, 2, 'What is a synonym, and what is an antonym? Give one example pair of each.', 'A synonym is a word that has nearly the same meaning as another word (e.g., "happy" and "joyful"). An antonym is a word that has the opposite meaning of another word (e.g., "hot" and "cold"). SSC exams frequently test both to assess vocabulary strength.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q04', 'ssc-english-bank', 'English Language & Grammar', 0, 3, 'What does "one-word substitution" mean in English grammar, and give an example.', 'One-word substitution means replacing a phrase or a whole sentence with a single word that conveys the same meaning. For example, "a person who studies birds" can be substituted with the single word "ornithologist".', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q05', 'ssc-english-bank', 'English Language & Grammar', 0, 4, 'What is an idiom? Give an example and explain its meaning.', 'An idiom is a phrase whose meaning cannot be understood from the literal meanings of its individual words; it carries a figurative meaning understood through common usage. For example, "to let the cat out of the bag" means to accidentally reveal a secret.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q06', 'ssc-english-bank', 'English Language & Grammar', 0, 5, 'What does "spotting errors" mean in SSC English papers, and what are common error types tested?', '"Spotting errors" is a question type where a sentence is divided into parts, and the candidate must identify which part (if any) contains a grammatical error. Common error types include subject-verb agreement, incorrect tense usage, wrong preposition, article errors, and pronoun-antecedent mismatches.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q07', 'ssc-english-bank', 'English Language & Grammar', 0, 6, 'What is the rule for choosing between the prepositions "in," "on," and "at" for time expressions?', '"In" is used for longer periods (months, years, seasons) — e.g., "in May," "in 2024." "On" is used for specific days and dates — e.g., "on Monday," "on 15th August." "At" is used for precise times — e.g., "at 5 PM," "at noon."', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q08', 'ssc-english-bank', 'English Language & Grammar', 0, 7, 'What does "sentence improvement" test, and what should a candidate check first?', 'Sentence improvement questions give a sentence with an underlined part and ask the candidate to choose the best replacement (or "No improvement") to make the sentence grammatically correct and stylistically clear. The candidate should first check if the original sentence is already correct before assuming a change is needed.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q09', 'ssc-english-bank', 'English Language & Grammar', 0, 8, 'What is a "para jumble" question, and what is the recommended strategy to solve it?', 'A para jumble question presents several sentences in random order that, when correctly arranged, form a coherent paragraph. The recommended strategy is to find the opening sentence (usually introduces the topic without pronouns referring back), identify linking words (pronouns, conjunctions like "however," "therefore") that connect consecutive sentences, and build the sequence from these connections.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q10', 'ssc-english-bank', 'English Language & Grammar', 0, 9, 'Why is "definately" considered a common spelling error, and what is the correct spelling?', '"Definately" is a common misspelling; the correct spelling is "definitely" — it is formed from "definite" plus "ly," not from "definate." Such frequently misspelled words are a staple of SSC spelling-based questions.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q11', 'ssc-english-bank', 'English Language & Grammar', 0, 10, 'When should the definite article "the" be used versus no article at all, with proper nouns?', '"The" is generally NOT used before most singular proper nouns (names of people, countries, cities) — e.g., "India," "Mumbai." However, "the" IS used before names of rivers, oceans, mountain ranges, groups of islands, and plural country names — e.g., "the Ganga," "the Himalayas," "the United States."', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q12', 'ssc-english-bank', 'English Language & Grammar', 0, 11, 'What is "subject-verb agreement," and give an example of a common error.', 'Subject-verb agreement means the verb in a sentence must match its subject in number (singular/plural). A common error occurs with collective nouns or phrases between subject and verb — e.g., incorrectly writing "The list of items are on the table" instead of the correct "The list of items is on the table," since "list" (singular) is the true subject.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q13', 'ssc-english-bank', 'English Language & Grammar', 0, 12, 'What is the difference between the present perfect tense and the simple past tense, with an example?', 'The simple past tense describes a completed action at a specific, finished time (e.g., "I visited Delhi last year"). The present perfect tense describes an action that happened at an unspecified time in the past and has relevance to the present, or an action that started in the past and continues now (e.g., "I have visited Delhi" — without saying when, or "I have lived here for five years").', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q14', 'ssc-english-bank', 'English Language & Grammar', 0, 13, 'What is a "cloze test," and what skill does it primarily assess?', 'A cloze test is a passage with several words removed and replaced with blanks; the candidate must choose the most appropriate word for each blank from given options. It primarily assesses vocabulary, grammar, and comprehension of context, since the correct word choice depends on understanding the overall meaning and flow of the passage.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('ssc-q15', 'ssc-english-bank', 'English Language & Grammar', 0, 14, 'In reading comprehension questions, why is it important to identify the "main idea" of a passage before answering specific questions?', 'Identifying the main idea gives the reader a framework for understanding how each paragraph and detail supports the author''s central point, which makes it easier to correctly answer questions about tone, inference, and specific facts without having to re-read the entire passage for every question.', '2026-11-12T13:50:45.454Z');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('banking-awareness-bank', NULL, 'Banking & Financial Awareness', 'banking', 'shared', '2026-11-12T13:50:45.454Z', '2026-11-12T13:50:45.454Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('banking-awareness-bank', 'banking-exam');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q01', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 0, 'What does "repo rate" mean, and which institution sets it in India?', 'Repo rate is the rate at which the Reserve Bank of India (RBI) lends short-term funds to commercial banks against government securities. It is a key tool of monetary policy — raising the repo rate makes borrowing costlier for banks (who then raise their own lending rates), helping control inflation; lowering it stimulates borrowing and economic growth.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q02', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 1, 'What is the difference between "repo rate" and "reverse repo rate"?', 'Repo rate is the rate at which RBI lends money to commercial banks. Reverse repo rate is the rate at which RBI borrows money from commercial banks, effectively absorbing excess liquidity from the banking system. Reverse repo rate is typically lower than the repo rate.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q03', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 2, 'What does "CRR" stand for, and what is its purpose?', 'CRR stands for Cash Reserve Ratio — the minimum percentage of a bank''s total deposits that it must keep as reserves with the RBI in cash form, and cannot lend out or invest. It is used by RBI to control the money supply and liquidity in the banking system.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q04', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 3, 'What does "SLR" stand for, and how does it differ from CRR?', 'SLR stands for Statutory Liquidity Ratio — the minimum percentage of a bank''s net demand and time liabilities that it must maintain in the form of liquid assets like cash, gold, or approved government securities, before offering credit. Unlike CRR (which must be held as cash with RBI), SLR assets are held by the bank itself and can include interest-earning securities.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q05', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 4, 'What is a "Non-Performing Asset (NPA)" in banking terminology?', 'An NPA is a loan or advance for which the principal or interest payment has remained overdue for a period of 90 days or more. Banks classify NPAs into sub-categories (substandard, doubtful, loss assets) based on how long they have remained unpaid, and must set aside provisions against them, affecting bank profitability.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q06', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 5, 'What is the full form of "IFSC," and what is its purpose?', 'IFSC stands for Indian Financial System Code — an 11-character alphanumeric code that uniquely identifies a specific bank branch participating in electronic fund transfer systems like NEFT, RTGS, and IMPS, ensuring that money is routed to the correct branch.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q07', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 6, 'What is the difference between NEFT, RTGS, and IMPS?', 'NEFT (National Electronic Funds Transfer) processes transactions in batches with half-hourly settlement cycles and no minimum/maximum limit. RTGS (Real Time Gross Settlement) processes transactions individually and immediately, used for high-value transfers above Rs. 2 lakh. IMPS (Immediate Payment Service) enables instant, 24x7, real-time fund transfer, typically for smaller amounts, available even on holidays.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q08', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 7, 'What is the role of the Deposit Insurance and Credit Guarantee Corporation (DICGC)?', 'DICGC, a wholly-owned subsidiary of the RBI, insures bank deposits up to a specified limit (currently Rs. 5 lakh per depositor per bank) in case a bank fails or is liquidated, protecting small depositors'' savings.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q09', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 8, 'What is "priority sector lending" in Indian banking?', 'Priority sector lending refers to RBI-mandated lending targets that banks must meet for specific sectors considered important for the nation''s economic and social development — including agriculture, micro/small/medium enterprises (MSMEs), export credit, education, housing, and weaker sections — to ensure credit flow to underserved segments of the economy.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q10', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 9, 'What does "KYC" stand for in banking, and why is it required?', 'KYC stands for "Know Your Customer" — a mandatory process where banks verify the identity and address of customers using documents like Aadhaar, PAN, and passport before opening an account or conducting transactions, to prevent fraud, money laundering, and identity theft.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q11', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 10, 'What is the difference between a "scheduled bank" and a "non-scheduled bank" in India?', 'A scheduled bank is one listed in the Second Schedule of the RBI Act, 1934, meeting criteria like a minimum paid-up capital, and is eligible for loans from RBI at bank rate and membership in clearing houses. A non-scheduled bank does not meet these criteria and is not listed in the schedule, so it does not enjoy these facilities.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q12', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 11, 'What is a "Non-Banking Financial Company (NBFC)," and how does it differ from a bank?', 'An NBFC is a company registered under the Companies Act that provides banking-like services (loans, credit facilities, asset financing) but cannot accept demand deposits, cannot issue cheques drawn on itself, and is not part of the payment and settlement system in the same way as a bank, and is regulated by RBI under a different framework.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q13', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 12, 'What is the purpose of the "Pradhan Mantri Jan Dhan Yojana (PMJDY)"?', 'PMJDY is a national financial inclusion scheme launched in 2014 to ensure every household in India has access to basic banking services — including a zero-balance savings account, debit card, accident insurance cover, and overdraft facility — aimed at bringing unbanked populations into the formal financial system.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q14', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 13, 'What is the difference between a "debit card" and a "credit card"?', 'A debit card draws money directly from the cardholder''s own bank account at the time of a transaction, so spending is limited to the available balance. A credit card allows the holder to borrow money from the issuing bank up to a pre-approved credit limit, which must be repaid later (often with interest if not paid in full by the due date).', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('banking-q15', 'banking-awareness-bank', 'Banking & Financial Awareness', 0, 14, 'What is "inflation targeting," and what is India''s current inflation target framework?', 'Inflation targeting is a monetary policy framework where the central bank sets an explicit numerical target for inflation and adjusts policy tools (like the repo rate) to keep inflation within that range. India''s Monetary Policy Committee (MPC) currently targets Consumer Price Index (CPI) inflation at 4%, with a tolerance band of +/-2% (i.e., 2% to 6%).', '2026-11-12T13:50:45.454Z');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('teaching-pedagogy-bank', NULL, 'Child Development & Pedagogy', 'teaching', 'shared', '2026-11-12T13:50:45.454Z', '2026-11-12T13:50:45.454Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('teaching-pedagogy-bank', 'teaching-exam');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q01', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 0, 'What is the main focus of Jean Piaget''s theory of cognitive development?', 'Piaget''s theory proposes that children''s cognitive development progresses through four distinct stages — sensorimotor, preoperational, concrete operational, and formal operational — each marked by qualitatively different ways of thinking, and that children actively construct knowledge through interaction with their environment rather than passively absorbing information.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q02', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 1, 'According to Piaget, what characterizes the "preoperational stage" of cognitive development?', 'The preoperational stage (roughly ages 2-7) is characterized by symbolic thinking (use of language and pretend play) but also by egocentrism (difficulty seeing things from others'' perspectives) and a lack of conservation (inability to understand that quantity remains the same despite changes in shape or arrangement).', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q03', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 2, 'What is Lev Vygotsky''s concept of the "Zone of Proximal Development (ZPD)"?', 'The ZPD is the gap between what a learner can do independently and what they can achieve with guidance or collaboration from a more knowledgeable other (teacher, peer, or adult). Vygotsky emphasized that effective teaching should target this zone, providing "scaffolding" that gradually withdraws as the learner becomes more capable.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q04', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 3, 'What is "scaffolding" in the context of teaching, and who is it associated with?', 'Scaffolding refers to the temporary support provided by a teacher or more knowledgeable peer to help a learner accomplish a task within their Zone of Proximal Development; the support is gradually reduced as the learner''s competence increases. The concept is closely associated with Vygotsky''s sociocultural theory of learning.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q05', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 4, 'What is the difference between "formative assessment" and "summative assessment"?', 'Formative assessment is conducted during the learning process to monitor student progress and provide ongoing feedback that can be used to adjust teaching (e.g., quizzes, class discussions). Summative assessment is conducted at the end of an instructional period to evaluate overall learning against a standard (e.g., final exams, unit tests).', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q06', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 5, 'What does "inclusive education" mean, and what is its primary goal?', 'Inclusive education means educating children with diverse abilities, including those with disabilities and special needs, together with their typically developing peers in the same mainstream classroom, with appropriate support. Its primary goal is to ensure equal access to quality education for all children, regardless of their physical, intellectual, social, or emotional differences.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q07', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 6, 'What is the difference between "intelligence" and "creativity" according to educational psychology?', 'Intelligence generally refers to the capacity to acquire knowledge, reason, solve problems, and adapt to the environment, often measured via IQ tests. Creativity refers to the ability to generate novel, original, and useful ideas or solutions, and does not always correlate directly with high intelligence scores — a person can be highly creative without having an exceptionally high IQ, and vice versa.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q08', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 7, 'What is Howard Gardner''s theory of "Multiple Intelligences"?', 'Gardner''s theory proposes that intelligence is not a single general ability but consists of multiple distinct types, including linguistic, logical-mathematical, spatial, musical, bodily-kinesthetic, interpersonal, intrapersonal, and naturalistic intelligence, suggesting that individuals have different strengths across these domains rather than one fixed IQ.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q09', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 8, 'What is the key difference between "classical conditioning" and "operant conditioning"?', 'Classical conditioning (Pavlov) involves learning through association, where a neutral stimulus becomes linked with a stimulus that naturally produces a response (e.g., a dog salivating at a bell after it''s repeatedly paired with food). Operant conditioning (Skinner) involves learning through consequences — behavior followed by reinforcement is strengthened, while behavior followed by punishment is weakened.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q10', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 9, 'What is "positive reinforcement" in classroom management, and give an example?', 'Positive reinforcement is a technique where a desirable consequence (reward, praise, privilege) is given after a desired behavior, increasing the likelihood that the behavior will be repeated. For example, praising a student for raising their hand before speaking encourages them to continue doing so.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q11', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 10, 'What does "child-centered education" emphasize, in contrast to a "teacher-centered" approach?', 'Child-centered education places the learner''s interests, needs, and pace of development at the center of the teaching process, encouraging active exploration, discovery, and self-directed learning. A teacher-centered approach, by contrast, positions the teacher as the primary source of knowledge, with students largely receiving information passively through lectures.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q12', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 11, 'What is the significance of the National Education Policy (NEP) 2020''s "5+3+3+4" structure?', 'The NEP 2020 restructured the school education system into four stages based on children''s cognitive development: Foundational (ages 3-8, 5 years), Preparatory (ages 8-11, 3 years), Middle (ages 11-14, 3 years), and Secondary (ages 14-18, 4 years) — replacing the earlier 10+2 structure to better align schooling with developmental stages.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q13', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 12, 'What is a "learning disability," and how does it differ from an intellectual disability?', 'A learning disability is a neurological condition that affects specific skills like reading (dyslexia), writing (dysgraphia), or mathematics (dyscalculia), in individuals who otherwise have average or above-average intelligence. An intellectual disability, by contrast, involves significantly below-average general intellectual functioning along with limitations in adaptive behavior, affecting overall cognitive ability more broadly.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q14', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 13, 'What is the difference between "formal" and "informal" assessment methods used by teachers?', 'Formal assessment uses standardized, structured tools (tests, exams) with fixed scoring criteria to measure learning against a benchmark. Informal assessment uses less structured, everyday methods (observation, class participation, questioning, portfolios) to gather ongoing insight into student understanding without the rigidity of standardized testing.', '2026-11-12T13:50:45.454Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('teaching-q15', 'teaching-pedagogy-bank', 'Child Development & Pedagogy', 0, 14, 'What is "socialization" in the context of child development, and which agencies primarily influence it?', 'Socialization is the lifelong process through which an individual learns and internalizes the values, norms, behaviors, and social skills appropriate to their society and culture. Its primary agencies include the family (the earliest and most influential), school, peer groups, and media, each shaping different aspects of a child''s social development.', '2026-11-12T13:50:45.454Z');
